import "sort"

// lengthOfLIS returns the length of the longest strictly increasing
// subsequence of nums. The subsequence need not be contiguous.
func lengthOfLIS(nums []int) int {
	// tails[k] is the smallest value that can end an increasing subsequence
	// of length k+1 seen so far, so tails is sorted and its length is the answer.
	tails := make([]int, 0, len(nums))
	for _, v := range nums {
		// Lower bound: the first tail >= v is the one v replaces. Upper bound
		// here would let v extend a run that already ends in v, counting
		// equal values as increasing.
		i := sort.SearchInts(tails, v)
		if i == len(tails) {
			tails = append(tails, v)
		} else {
			tails[i] = v
		}
	}
	return len(tails)
}

