const oracleMod = 1_000_000_007

// gridOracle is the O(rows*cols) table, usable only on small grids.
func gridOracle(rows, cols int, blocked [][2]int) int {
	bad := make(map[[2]int]bool, len(blocked))
	for _, b := range blocked {
		bad[b] = true
	}
	prev := make([]int, cols)
	cur := make([]int, cols)
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			switch {
			case bad[[2]int{r, c}]:
				cur[c] = 0
			case r == 0 && c == 0:
				cur[c] = 1
			default:
				v := 0
				if r > 0 {
					v += prev[c]
				}
				if c > 0 {
					v += cur[c-1]
				}
				cur[c] = v % oracleMod
			}
		}
		prev, cur = cur, prev
	}
	return prev[cols-1]
}

