// TestPathsHugeGrid is 500000 x 500000, far past any table, and grades itself
// with two identities: a cell's count is the sum of the counts above and to
// the left of it, and blocking one cell removes exactly the paths through it.
func TestPathsHugeGrid(t *testing.T) {
	const rows, cols = 500000, 500000
	open := countPaths(rows, cols, nil)
	if open == 0 {
		t.Fatal("open 500000x500000 grid: got 0 paths")
	}
	up := countPaths(rows-1, cols, nil)
	left := countPaths(rows, cols-1, nil)
	if want := (up + left) % oracleMod; open != want {
		t.Fatalf("P(r,c) = P(r-1,c)+P(r,c-1): got %d, want %d", open, want)
	}
	const br, bc = 123456, 345678
	through := countPaths(br+1, bc+1, nil) * countPaths(rows-br, cols-bc, nil) % oracleMod
	want := ((open-through)%oracleMod + oracleMod) % oracleMod
	if got := countPaths(rows, cols, [][2]int{{br, bc}}); got != want {
		t.Fatalf("one blocked cell: got %d, want %d", got, want)
	}
}

