import "sort"

const pathsMod = 1_000_000_007

// countPaths returns, modulo 1_000_000_007, the number of paths from the top
// left cell to the bottom right cell of a rows x cols grid that step only
// right or down and never enter a blocked cell. Each blocked entry is
// {row, col}.
func countPaths(rows, cols int, blocked [][2]int) int {
	if rows <= 0 || cols <= 0 {
		return 0
	}
	n := rows + cols
	fact := make([]int, n+1)
	invFact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i % pathsMod
	}
	invFact[n] = pathsPow(fact[n], pathsMod-2)
	for i := n; i > 0; i-- {
		invFact[i-1] = invFact[i] * i % pathsMod
	}
	// ways is the unobstructed count for a move of dr down and dc right.
	ways := func(dr, dc int) int {
		if dr < 0 || dc < 0 {
			return 0
		}
		return fact[dr+dc] * invFact[dr] % pathsMod * invFact[dc] % pathsMod
	}
	pts := make([][2]int, 0, len(blocked)+1)
	for _, b := range blocked {
		if b[0] >= 0 && b[0] < rows && b[1] >= 0 && b[1] < cols {
			pts = append(pts, b)
		}
	}
	sort.Slice(pts, func(i, j int) bool {
		if pts[i][0] != pts[j][0] {
			return pts[i][0] < pts[j][0]
		}
		return pts[i][1] < pts[j][1]
	})
	pts = append(pts, [2]int{rows - 1, cols - 1})
	// f[i] counts paths reaching pts[i] whose first blocked cell is pts[i],
	// so the paths counted for different i are disjoint.
	f := make([]int, len(pts))
	for i, p := range pts {
		f[i] = ways(p[0], p[1])
		for j := 0; j < i; j++ {
			if pts[j][0] <= p[0] && pts[j][1] <= p[1] {
				f[i] = (f[i] - f[j]*ways(p[0]-pts[j][0], p[1]-pts[j][1])) % pathsMod
			}
		}
		f[i] = (f[i]%pathsMod + pathsMod) % pathsMod
	}
	return f[len(f)-1]
}

func pathsPow(base, exp int) int {
	res := 1
	base %= pathsMod
	for exp > 0 {
		if exp&1 == 1 {
			res = res * base % pathsMod
		}
		base = base * base % pathsMod
		exp >>= 1
	}
	return res
}

