// exprNode is a random expression that knows its own value, so the test grades
// without a second parser.
type exprNode struct {
	op          byte // 0 for a literal
	val         int
	left, right *exprNode
}

func exprPrec(n *exprNode) int {
	switch n.op {
	case 0:
		return 3
	case '*', '/':
		return 2
	}
	return 1
}

// exprEmit prints the tree, dropping parentheses only where precedence and
// left associativity already give the same reading.
func exprEmit(n, parent *exprNode, isRight bool) string {
	if n.op == 0 {
		return strconv.Itoa(n.val)
	}
	s := exprEmit(n.left, n, false) + string(n.op) + exprEmit(n.right, n, true)
	if parent == nil {
		return s
	}
	if exprPrec(n) < exprPrec(parent) || (isRight && exprPrec(n) <= exprPrec(parent)) {
		return "(" + s + ")"
	}
	return s
}

func exprBuild(rng *rand.Rand, depth int) *exprNode {
	if depth == 0 || rng.Intn(3) == 0 {
		return &exprNode{val: rng.Intn(50)}
	}
	l := exprBuild(rng, depth-1)
	r := exprBuild(rng, depth-1)
	op := "+-*/"[rng.Intn(4)]
	if op == '/' && r.val == 0 {
		op = '+'
	}
	n := &exprNode{op: op, left: l, right: r}
	switch op {
	case '+':
		n.val = l.val + r.val
	case '-':
		n.val = l.val - r.val
	case '*':
		n.val = l.val * r.val
	case '/':
		n.val = l.val / r.val
	}
	return n
}

