// evaluate returns the value of an arithmetic expression made of non-negative
// integer literals, the operators + - * and /, parentheses and spaces.
// Division truncates toward zero and never divides by zero; a leading - is a
// unary minus.
func evaluate(expr string) int {
	p := &exprParser{src: expr}
	return p.sum()
}

// exprParser walks the string once, one grammar level per precedence level.
type exprParser struct {
	src string
	pos int
}

// next reports the next meaningful byte without consuming it, 0 at the end.
func (p *exprParser) next() byte {
	for p.pos < len(p.src) && p.src[p.pos] == ' ' {
		p.pos++
	}
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

// sum is the lowest level: a run of terms joined by + and -.
func (p *exprParser) sum() int {
	v := p.term()
	for {
		switch p.next() {
		case '+':
			p.pos++
			v += p.term()
		case '-':
			p.pos++
			v -= p.term()
		default:
			return v
		}
	}
}

// term binds tighter: a run of factors joined by * and /.
func (p *exprParser) term() int {
	v := p.factor()
	for {
		switch p.next() {
		case '*':
			p.pos++
			v *= p.factor()
		case '/':
			p.pos++
			v /= p.factor()
		default:
			return v
		}
	}
}

// factor is a literal, a parenthesised expression, or a signed factor.
func (p *exprParser) factor() int {
	switch p.next() {
	case '-':
		p.pos++
		return -p.factor()
	case '+':
		p.pos++
		return p.factor()
	case '(':
		p.pos++
		v := p.sum()
		if p.next() == ')' {
			p.pos++
		}
		return v
	}
	n := 0
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		n = n*10 + int(p.src[p.pos]-'0')
		p.pos++
	}
	return n
}
